#!/bin/sh
# A generated lab file names its generator and every source by repository path on line 1:
#   // GENERATED by <generator path> from <path>[, <path>...] ...
# and each named path exists, so the parity derivation of landing.md §3 can follow
# design/ and records edits through the generated file to the pages (Wren, 2026-10-25).
set -eu
cd "$(dirname "$0")/.."
rc=0
for f in lab/web/*.js; do
    line=$(head -1 "$f")
    case "$line" in
        "// GENERATED by "*|"// generated by "*) ;;
        *) continue ;;
    esac
    paths=$(printf '%s\n' "$line" | sed 's|^// [Gg][Ee][Nn][Ee][Rr][Aa][Tt][Ee][Dd] by ||' | tr ',;()' '    ' | tr -s ' ' '\n' | sed 's/[.:]*$//' | grep -E '^[A-Za-z0-9_.*-]+(/[A-Za-z0-9_.*-]+)+$' || true)
    gen=$(printf '%s\n' "$paths" | head -1)
    if [ -z "$gen" ]; then
        echo "generated-sources: $f line 1 names no generator by repository path" >&2; rc=1; continue
    fi
    n=$(printf '%s\n' "$paths" | wc -l | tr -d ' ')
    if [ "$n" -lt 2 ]; then
        echo "generated-sources: $f line 1 names no source by repository path" >&2; rc=1
    fi
    for p in $paths; do
        # a glob names a set; at least one file must match it
        set +f; found=0; for m in $p; do [ -e "$m" ] && found=1 && break; done
        [ $found -eq 1 ] || { echo "generated-sources: $f line 1 names $p, which does not exist" >&2; rc=1; }
    done
done
[ $rc -eq 0 ] && echo "generated-sources: held"
exit $rc
